(() => {
  'use strict';

  const ROOT_ID = 'ffws-br-s2-stats';
  const SECTION_ID = 'anchor-s2-evolucao-jogadores';
  const DATA_URL = 'ffws-br-2026-s2/players.json?v=20260905-player-evolution-v1';
  const MAX_SELECTED = 5;
  const palette = ['#00c8ff', '#ffd34d', '#7fe29a', '#ff7a90', '#b68cff'];
  const state = {
    loading: null,
    data: null,
    top10: [],
    selected: [],
    metric: 'kills',
    query: '',
    chart: null,
    observer: null,
    chartRetry: 0
  };

  const number = value => Number(value) || 0;
  const normalize = value => String(value || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/gi, '').toUpperCase();
  const escapeHtml = value => String(value ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#039;');

  function stageKey(value) {
    const key = normalize(value);
    if (key === 'SEGUNDAFASE' || key === 'SEGUNDA' || key === '2FASE') return 'segundaFase';
    if (key === 'FINAL') return 'final';
    return 'classificatoria';
  }

  function stageOrder(value) {
    const key = stageKey(value);
    return key === 'classificatoria' ? 0 : key === 'segundaFase' ? 1 : 2;
  }

  function stageShort(value) {
    const key = stageKey(value);
    return key === 'classificatoria' ? 'CLASS.' : key === 'segundaFase' ? '2ª FASE' : 'FINAL';
  }

  function injectCss() {
    if (document.getElementById('cff-s2-player-evolution-css')) return;
    const style = document.createElement('style');
    style.id = 'cff-s2-player-evolution-css';
    style.textContent = `
      .cff-s2-player-evo-controls{display:grid;grid-template-columns:minmax(180px,260px) minmax(220px,1fr);gap:14px;align-items:end;margin-bottom:16px}
      .cff-s2-player-search-wrap{position:relative;min-width:0}
      .cff-s2-player-search-wrap>span,.cff-s2-player-picker>span{display:block;color:var(--text-muted);font-size:.72rem;font-weight:900;text-transform:uppercase;letter-spacing:.045em;margin-bottom:6px}
      .cff-s2-player-search{width:100%;min-width:0;height:42px;border:1px solid var(--border);border-radius:8px;background:#0d1320;color:#fff;padding:0 12px;font:inherit;font-size:.88rem;box-sizing:border-box;outline:none}
      .cff-s2-player-search:focus{border-color:var(--accent);box-shadow:0 0 0 2px rgba(0,200,255,.12)}
      .cff-s2-player-picker{grid-column:1/-1;min-width:0}
      .cff-s2-player-buttons{display:flex;flex-wrap:wrap;gap:8px}
      .cff-s2-player-btn{display:flex;align-items:center;gap:7px;min-height:38px;padding:6px 10px;border:1px solid rgba(120,147,181,.25);border-radius:8px;background:rgba(255,255,255,.025);color:#dcecff;cursor:pointer;font:inherit;font-size:.78rem;font-weight:850;transition:.15s ease;max-width:220px}
      .cff-s2-player-btn:hover{border-color:rgba(0,200,255,.55);background:rgba(0,200,255,.07)}
      .cff-s2-player-btn.active{border-color:var(--accent);background:rgba(0,200,255,.12);color:#fff}
      .cff-s2-player-btn .rank{color:var(--accent);font-weight:1000;min-width:22px}
      .cff-s2-player-btn .name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:125px}
      .cff-s2-player-btn .team{color:#7893b5;font-size:.7rem;font-weight:900}
      .cff-s2-player-picker-empty{color:var(--text-muted);font-size:.8rem;padding:10px 0}
      .cff-s2-player-evo-note{margin:8px 0 0;color:#7893b5;font-size:.72rem;font-weight:750;line-height:1.4}
      .cff-s2-player-evo-canvas{height:340px;position:relative}
      @media(max-width:700px){
        .cff-s2-player-evo-controls{grid-template-columns:1fr;gap:10px}
        .cff-s2-player-picker{grid-column:auto}
        .cff-s2-player-search{font-size:16px}
        .cff-s2-player-buttons{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}
        .cff-s2-player-btn{width:100%;max-width:none;min-width:0;padding:6px 8px}
        .cff-s2-player-btn .name{max-width:none;min-width:0;flex:1;text-align:left}
        .cff-s2-player-btn .team{display:none}
        .cff-s2-player-evo-canvas{height:300px}
      }
    `;
    document.head.appendChild(style);
  }

  async function loadData() {
    if (state.data) return state.data;
    if (state.loading) return state.loading;
    state.loading = fetch(DATA_URL, { cache: 'default' })
      .then(response => {
        if (!response.ok) throw new Error(`Falha ao carregar ${DATA_URL}`);
        return response.json();
      })
      .then(data => {
        state.data = data || { players: [], entries: [] };
        buildTop10();
        return state.data;
      })
      .finally(() => { state.loading = null; });
    return state.loading;
  }

  function entries() {
    return Array.isArray(state.data?.entries) ? state.data.entries : [];
  }

  function rosterMeta(name, team) {
    const list = Array.isArray(state.data?.players) ? state.data.players : [];
    const nk = normalize(name), tk = normalize(team);
    return list.find(player => {
      const aliases = [player?.name, player?.sourceName, ...(Array.isArray(player?.aliases) ? player.aliases : [])];
      return aliases.some(alias => normalize(alias) === nk) && (!tk || normalize(player?.team) === tk);
    }) || null;
  }

  function buildTop10() {
    const map = new Map();
    entries().forEach(entry => {
      const name = String(entry?.name || entry?.player || '').trim();
      const team = String(entry?.team || entry?.equipe || '').trim();
      if (!name) return;
      const key = `${normalize(name)}__${normalize(team)}`;
      if (!map.has(key)) map.set(key, { key, name, team, kills: 0, damage: 0, assists: 0, matches: 0 });
      const row = map.get(key);
      row.kills += number(entry?.kills ?? entry?.abates);
      row.damage += number(entry?.damage ?? entry?.dano);
      row.assists += number(entry?.assists ?? entry?.assistencias);
      row.matches += number(entry?.matches ?? entry?.quedas) || 1;
    });
    state.top10 = [...map.values()]
      .sort((a, b) => b.kills - a.kills || b.damage - a.damage || b.assists - a.assists || a.name.localeCompare(b.name, 'pt-BR'))
      .slice(0, 10)
      .map((row, index) => {
        const meta = rosterMeta(row.name, row.team);
        return { ...row, rank: index + 1, teamAbbreviation: meta?.teamAbbreviation || meta?.teamShort || String(row.team || '').slice(0, 4).toUpperCase() };
      });
    const allowed = new Set(state.top10.map(row => row.key));
    state.selected = state.selected.filter(key => allowed.has(key));
    if (!state.selected.length) state.selected = state.top10.slice(0, Math.min(3, state.top10.length)).map(row => row.key);
  }

  function currentRecorte() {
    const filterRoot = document.getElementById('anchor-s2-filtros');
    const stageSelect = filterRoot?.querySelector('.ffws-s2-filters label.ffws-s2-filter select') || filterRoot?.querySelector('.ffws-s2-filters select');
    const stage = String(stageSelect?.value || 'classificatoria');
    const days = [...document.querySelectorAll('#ffws-s2-stats-multi-days input[value]:checked')].map(input => String(input.value));
    const maps = [...document.querySelectorAll('#ffws-s2-stats-multi-maps input[value]:checked')].map(input => String(input.value));
    return { stage, days, maps };
  }

  function filteredEntries() {
    const recorte = currentRecorte();
    const allowedStages = recorte.stage === 'geral' ? new Set(['classificatoria', 'segundaFase', 'final']) : new Set([stageKey(recorte.stage)]);
    return entries().filter(entry => {
      const entryStage = stageKey(entry?.stage);
      const day = String(number(entry?.day ?? entry?.dia ?? entry?.round ?? entry?.rodada));
      const map = String(entry?.map || entry?.mapa || '').trim();
      return allowedStages.has(entryStage)
        && (!recorte.days.length || recorte.days.includes(day))
        && (!recorte.maps.length || recorte.maps.some(item => normalize(item) === normalize(map)));
    });
  }

  function periodsFor(rows) {
    const map = new Map();
    rows.forEach(entry => {
      const stage = stageKey(entry?.stage);
      const day = number(entry?.day ?? entry?.dia ?? entry?.round ?? entry?.rodada);
      if (!day) return;
      const key = `${stage}__${day}`;
      if (!map.has(key)) map.set(key, { key, stage, day });
    });
    return [...map.values()].sort((a, b) => stageOrder(a.stage) - stageOrder(b.stage) || a.day - b.day);
  }

  function periodMatches(entry, period) {
    return stageKey(entry?.stage) === period.stage
      && number(entry?.day ?? entry?.dia ?? entry?.round ?? entry?.rodada) === period.day;
  }

  function playerRowByKey(key) {
    return state.top10.find(row => row.key === key) || null;
  }

  function metricSeries(rows, periods, player, metric) {
    return periods.map(period => {
      const playerRows = rows.filter(entry => periodMatches(entry, period)
        && normalize(entry?.name || entry?.player) === normalize(player.name)
        && normalize(entry?.team || entry?.equipe) === normalize(player.team));
      if (!playerRows.length) return null;
      const kills = playerRows.reduce((sum, entry) => sum + number(entry?.kills ?? entry?.abates), 0);
      if (metric === 'kills') return kills;
      if (metric === 'assists') return playerRows.reduce((sum, entry) => sum + number(entry?.assists ?? entry?.assistencias), 0);
      if (metric === 'damage') return playerRows.reduce((sum, entry) => sum + number(entry?.damage ?? entry?.dano), 0);
      const teamKills = rows.filter(entry => periodMatches(entry, period) && normalize(entry?.team || entry?.equipe) === normalize(player.team))
        .reduce((sum, entry) => sum + number(entry?.kills ?? entry?.abates), 0);
      return teamKills > 0 ? Number(((kills / teamKills) * 100).toFixed(1)) : 0;
    });
  }

  function stripTeamDescription() {
    const teamSection = document.getElementById('anchor-s2-evolucao');
    if (!teamSection) return null;
    const paragraphs = teamSection.querySelectorAll('.ffws-s2-panel-head p');
    paragraphs.forEach(paragraph => {
      if (paragraph.textContent.includes('Gráfico no mesmo estilo da S1')) paragraph.remove();
    });
    return teamSection;
  }

  function metricOptions() {
    return [
      ['kills', 'Abates'],
      ['assists', 'Assistência'],
      ['damage', 'Dano'],
      ['participation', 'Participação em kills da equipe %']
    ].map(([value, label]) => `<option value="${value}"${state.metric === value ? ' selected' : ''}>${label}</option>`).join('');
  }

  function playerButtonsHtml() {
    const query = normalize(state.query);
    const visible = state.top10.filter(row => !query || normalize(row.name).includes(query) || normalize(row.team).includes(query) || normalize(row.teamAbbreviation).includes(query));
    if (!visible.length) return '<div class="cff-s2-player-picker-empty">Nenhum jogador do Top 10 encontrado.</div>';
    return visible.map(row => `<button type="button" class="cff-s2-player-btn${state.selected.includes(row.key) ? ' active' : ''}" data-player-key="${escapeHtml(row.key)}" title="#${row.rank} ${escapeHtml(row.name)} • ${escapeHtml(row.team)}"><span class="rank">#${row.rank}</span><span class="name">${escapeHtml(row.name)}</span><span class="team">${escapeHtml(row.teamAbbreviation)}</span></button>`).join('');
  }

  function sectionHtml() {
    return `<section id="${SECTION_ID}" class="ffws-s2-panel ffws-s2-stats-evolution cff-s2-player-evolution"><div class="ffws-s2-panel-inner">
      <div class="ffws-s2-panel-head"><div><h2>Comparação de Evolução dos Jogadores</h2><p>Compare o desempenho por dia dentro do recorte selecionado acima.</p></div><span class="ffws-s2-badge">Top 10 MVP • até ${MAX_SELECTED}</span></div>
      <div class="cff-s2-player-evo-controls">
        <label class="ffws-s2-filter"><span>Métrica do gráfico:</span><select id="cff-s2-player-evo-metric">${metricOptions()}</select></label>
        <label class="cff-s2-player-search-wrap"><span>Pesquisar jogador</span><input id="cff-s2-player-evo-search" class="cff-s2-player-search" type="search" autocomplete="off" placeholder="Pesquisar no Top 10 do MVP..." value="${escapeHtml(state.query)}"></label>
        <div class="cff-s2-player-picker"><span>Jogadores do Top 10 do MVP (máx. ${MAX_SELECTED}):</span><div id="cff-s2-player-evo-buttons" class="cff-s2-player-buttons">${playerButtonsHtml()}</div><p class="cff-s2-player-evo-note">A lista de escolha é limitada aos 10 primeiros do Ranking MVP atual. Os pontos do gráfico respeitam Etapa, Dias e Mapa definidos nos filtros do torneio.</p></div>
      </div>
      <div class="ffws-s2-evolution-canvas-wrap cff-s2-player-evo-canvas"><canvas id="cff-s2-player-evolution-chart"></canvas><div id="cff-s2-player-evolution-empty" class="ffws-s2-empty" hidden><div><strong>Sem dados suficientes</strong>Selecione ao menos um jogador com resultados no recorte.</div></div></div>
    </div></section>`;
  }

  function bindSection() {
    const metric = document.getElementById('cff-s2-player-evo-metric');
    metric?.addEventListener('change', event => {
      state.metric = ['kills', 'assists', 'damage', 'participation'].includes(event.target.value) ? event.target.value : 'kills';
      renderChart();
    });
    const search = document.getElementById('cff-s2-player-evo-search');
    search?.addEventListener('input', event => {
      state.query = event.target.value || '';
      renderPlayerButtons();
    });
    document.getElementById('cff-s2-player-evo-buttons')?.addEventListener('click', event => {
      const button = event.target.closest('.cff-s2-player-btn');
      if (!button) return;
      togglePlayer(button.dataset.playerKey || '');
    });
  }

  function renderPlayerButtons() {
    const root = document.getElementById('cff-s2-player-evo-buttons');
    if (!root) return;
    root.innerHTML = playerButtonsHtml();
  }

  function togglePlayer(key) {
    if (!key) return;
    const selected = new Set(state.selected);
    if (selected.has(key)) selected.delete(key);
    else if (selected.size < MAX_SELECTED) selected.add(key);
    state.selected = [...selected];
    renderPlayerButtons();
    renderChart();
  }

  function renderChart() {
    const canvas = document.getElementById('cff-s2-player-evolution-chart');
    const empty = document.getElementById('cff-s2-player-evolution-empty');
    if (!canvas) return;
    if (!window.Chart) {
      if (state.chartRetry++ < 20) setTimeout(renderChart, 120);
      return;
    }
    state.chartRetry = 0;
    if (state.chart) {
      try { state.chart.destroy(); } catch (_) {}
      state.chart = null;
    }
    const rows = filteredEntries();
    const periods = periodsFor(rows);
    const players = state.selected.map(playerRowByKey).filter(Boolean);
    const datasets = players.map((player, index) => ({
      label: player.name,
      data: metricSeries(rows, periods, player, state.metric),
      borderColor: palette[index % palette.length],
      backgroundColor: palette[index % palette.length],
      tension: .2,
      borderWidth: 2.25,
      pointRadius: 3,
      pointHoverRadius: 5,
      spanGaps: true
    }));
    const hasData = periods.length && datasets.some(dataset => dataset.data.some(value => value !== null));
    canvas.hidden = !hasData;
    if (empty) empty.hidden = !!hasData;
    if (!hasData) return;
    const percent = state.metric === 'participation';
    const damage = state.metric === 'damage';
    const formatTick = value => percent ? `${value}%` : damage && Math.abs(value) >= 1000 ? `${(value / 1000).toFixed(value >= 10000 ? 0 : 1)}k` : value;
    state.chart = new window.Chart(canvas.getContext('2d'), {
      type: 'line',
      data: {
        labels: periods.map(period => `${stageShort(period.stage)} D${period.day}`),
        datasets
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: 'nearest', intersect: false },
        plugins: {
          legend: { labels: { color: '#dcecff', boxWidth: 14, boxHeight: 3 } },
          tooltip: { callbacks: { label: context => `${context.dataset.label}: ${percent ? `${Number(context.parsed.y).toFixed(1)}%` : Math.round(number(context.parsed.y)).toLocaleString('pt-BR')}` } }
        },
        scales: {
          x: { ticks: { color: '#7893b5', maxRotation: 0, autoSkip: true }, grid: { color: 'rgba(120,147,181,.10)' } },
          y: { beginAtZero: true, suggestedMax: percent ? 100 : undefined, ticks: { color: '#7893b5', precision: percent ? 1 : 0, callback: formatTick }, grid: { color: 'rgba(120,147,181,.10)' } }
        }
      }
    });
  }

  async function enhance() {
    const root = document.getElementById(ROOT_ID);
    if (!root) return;
    const teamSection = stripTeamDescription();
    if (!teamSection) return;
    if (document.getElementById(SECTION_ID)) return;
    try {
      await loadData();
      if (!document.getElementById(ROOT_ID) || !document.getElementById('anchor-s2-evolucao')) return;
      const section = document.createElement('div');
      section.innerHTML = sectionHtml();
      const node = section.firstElementChild;
      document.getElementById('anchor-s2-evolucao')?.insertAdjacentElement('afterend', node);
      bindSection();
      requestAnimationFrame(renderChart);
    } catch (error) {
      console.error('[S2 Player Evolution]', error);
    }
  }

  function boot() {
    injectCss();
    const root = document.getElementById(ROOT_ID);
    if (!root) return;
    if (!state.observer) {
      state.observer = new MutationObserver(() => { enhance(); });
      state.observer.observe(root, { childList: true, subtree: true });
    }
    enhance();
  }

  window.cffS2PlayerEvolutionBoot = boot;
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot, { once: true });
  else boot();
})();
